Input: {"question": "What is the size of Winter Island?", "source_segments": {"D1S1": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 0, "end": 103, "text": "Winter Island Winter Island is an island connected by a causeway to Salem Neck in Salem, Massachusetts."}, "D1S2": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 104, "end": 261, "text": "It is about in size, and is bounded by Smith Pool to the northwest, Cat Cove to the west, Salem Channel to the south and east, and Juniper Cove to the north."}, "D1S3": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 262, "end": 352, "text": "The island has about a dozen residences at the north end and one road, Winter Island Road."}, "D1S4": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 353, "end": 449, "text": "The Plummer Home for Boys (now Plummer Youth Promise) sits on of land on the northeastern shore."}, "D1S5": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 450, "end": 505, "text": "The balance of the island is Winter Island Marine Park."}, "D1S6": {"document_number": 1, "doc_id": "ramdocs-0163-66031241e443:d00", "start": 506, "end": 540, "text": "The entire island was added to the"}, "D2S1": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 0, "end": 89, "text": "Winter Island is an island connected by a causeway to Salem Neck in Salem, Massachusetts."}, "D2S2": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 90, "end": 264, "text": "It is about 100 square miles in size, and is bounded by Smith Pool to the northwest, Cat Cove to the west, Salem Channel to the south and east, and Juniper Cove to the north."}, "D2S3": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 265, "end": 355, "text": "The island has about a dozen residences at the north end and one road, Winter Island Road."}, "D2S4": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 356, "end": 461, "text": "The Plummer Home for Boys (now Plummer Youth Promise) sits on 10 acres of land on the northeastern shore."}, "D2S5": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 462, "end": 517, "text": "The balance of the island is Winter Island Marine Park."}, "D2S6": {"document_number": 2, "doc_id": "ramdocs-0163-66031241e443:d01", "start": 518, "end": 598, "text": "The entire island was added to the National Register of Historic Places in 1980."}, "D3S1": {"document_number": 3, "doc_id": "ramdocs-0163-66031241e443:d02", "start": 0, "end": 180, "text": "Winter Island (Antarctica) Winter Island is an island long, lying north of Skua Island in the Argentine Islands, Wilhelm Archipelago, off the west coast of Graham Land, Antarctica."}, "D3S2": {"document_number": 3, "doc_id": "ramdocs-0163-66031241e443:d02", "start": 181, "end": 323, "text": "Winter Island was named by the British Graham Land Expedition (BGLE), 1934–37, which made this island the site of its winter base during 1935."}, "D3S3": {"document_number": 3, "doc_id": "ramdocs-0163-66031241e443:d02", "start": 324, "end": 437, "text": "The Falkland Islands Dependencies Survey established a base on Winter Island in 1947, Base F (Argentine Islands)."}, "D3S4": {"document_number": 3, "doc_id": "ramdocs-0163-66031241e443:d02", "start": 438, "end": 623, "text": "The main hut, built on the site of the old BGLE hut, was named \"Wordie House\" after Sir James Wordie, a member of Shackleton's Imperial Trans-Antarctic Expedition who visited during its"}, "D4S1": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 0, "end": 67, "text": ", we will have to construct a new artefact for our religious need ."}, "D4S2": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 68, "end": 100, "text": "For that we will require stone ."}, "D4S3": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 101, "end": 194, "text": "To comfort our people , to repay them for the suffering , there is only one thing we can do ."}, "D4S4": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 195, "end": 201, "text": "Food ."}, "D4S5": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 202, "end": 216, "text": "Lots of food ."}, "D4S6": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 217, "end": 247, "text": "That makes everything better ."}, "D4S7": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 248, "end": 343, "text": "[ Great ] [ Pay 90 % 50 % ] You pay the reparations for your abhorrent crime and are released ."}, "D4S8": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 344, "end": 445, "text": "[ Death penalty ] : Oh , sorry , naked yeti , but we have abolished the death penalty long long ago ."}, "D4S9": {"document_number": 4, "doc_id": "ramdocs-0163-66031241e443:d03", "start": 446, "end": 455, "text": "After all"}, "D5S1": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 0, "end": 71, "text": "the cold is too severe , you can ’ t even think of any good arguments ."}, "D5S2": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 72, "end": 157, "text": "[ One more time ] [ Take off clothes ] : You act fast and take off your wet clothes ."}, "D5S3": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 158, "end": 201, "text": "Then you expose yourself to the warm fire ."}, "D5S4": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 202, "end": 241, "text": "In minutes you are dry and warm again ."}, "D5S5": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 242, "end": 295, "text": "The clothes are left near the fire for a bit longer ."}, "D5S6": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 296, "end": 348, "text": "When all dried , you are ready to put them back on ."}, "D5S7": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 349, "end": 360, "text": "Well done !"}, "D5S8": {"document_number": 5, "doc_id": "ramdocs-0163-66031241e443:d04", "start": 361, "end": 423, "text": "[ < -Yay ] The tracks [ ] Near the edge of the frozen lake you"}, "D6S1": {"document_number": 6, "doc_id": "ramdocs-0163-66031241e443:d05", "start": 0, "end": 118, "text": "group ’ s location with respect to the Kyiv Peninsula that projects from the western side of the Antarctic Peninsula ."}, "D6S2": {"document_number": 6, "doc_id": "ramdocs-0163-66031241e443:d05", "start": 119, "end": 225, "text": "The summer season provides enough daylight for satellites to acquire natural color images this far south ."}, "D6S3": {"document_number": 6, "doc_id": "ramdocs-0163-66031241e443:d05", "start": 226, "end": 395, "text": "It is also the time of year when sea ice around Antarctica has melted , making it easier to distinguish the ice-capped islands against the dark-blue Bellingshausen Sea ."}, "D6S4": {"document_number": 6, "doc_id": "ramdocs-0163-66031241e443:d05", "start": 396, "end": 559, "text": "Several days after these images were acquired , sea ice around Antarctica reached the lowest extent ever observed since the start of the satellite record in 1979 ."}, "D6S5": {"document_number": 6, "doc_id": "ramdocs-0163-66031241e443:d05", "start": 560, "end": 595, "text": "The low-ice trend continued through"}}, "candidates": [{"candidate_id": "C0", "answer": "about 100 square miles", "card_ids": ["ramdocs-0163-66031241e443:d01:c0"]}, {"candidate_id": "C1", "answer": "long", "card_ids": ["ramdocs-0163-66031241e443:d02:c0"]}], "original_cards": [{"doc_id": "ramdocs-0163-66031241e443:d01", "card_id": "ramdocs-0163-66031241e443:d01:c0", "entity": "Winter Island", "scope": "size", "claim": "Winter Island is about 100 square miles in size.", "answer": "about 100 square miles", "quote": "It is about 100 square miles in size, and is bounded by Smith Pool to the northwest, Cat Cove to the west, Salem Channel to the south and east, and Juniper Cove to the north.", "original_document_number": 2}, {"doc_id": "ramdocs-0163-66031241e443:d02", "card_id": "ramdocs-0163-66031241e443:d02:c0", "entity": "Winter Island", "scope": "Antarctica", "claim": "Winter Island is an island long, lying north of Skua Island in the Argentine Islands, Wilhelm Archipelago, off the west coast of Graham Land, Antarctica.", "answer": "long", "quote": "Winter Island (Antarctica) Winter Island is an island long, lying north of Skua Island in the Argentine Islands, Wilhelm Archipelago, off the west coast of Graham Land, Antarctica.", "original_document_number": 3}], "initial_answers": ["about 100 square miles"]}

